```python
def solve(s):
    has_letters = False
    result = []

    for char in s:
        if char.isalpha():
            has_letters = True
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)

    if not has_letters:
        result.reverse()

    return ''.join(result)

